"""Headless smoke tests of the window: builds it with fake data and checks bells / banner / dialogs."""
import json, os, sys, unittest
os.environ["QT_QPA_PLATFORM"] = "offscreen"
from pathlib import Path
sys.path.insert(0, str(Path(__file__).resolve().parent.parent))
from PySide6.QtTest import QTest
from PySide6.QtCore import Qt
from PySide6.QtWidgets import QApplication, QDialog, QPushButton
import protonupd as P
import protonupd_gui as G

app = QApplication.instance() or QApplication([])
REL = {"tag": "GE-Proton11-12", "name": "GE-Proton11-12-x86_64", "url": "u", "date": "2026-10-20", "size": 5 << 20,
       "sha": None, "page": "p"}


class Gui(unittest.TestCase):
    def setUp(self):
        import i18n; i18n.set_lang("en")                  # tests must not depend on the system language
        P.save = lambda c: None
        P.steam_running = lambda: False
        P.current_tool = lambda a: {"1": "GE-Proton11-12-x86_64", "2": "GE-Proton11-11-x86_64", "3": "GE-Proton11-9-x86_64"}.get(a)
        P.names = lambda: {}
        P.load = lambda: {"games": {"1": {"name": "A", "source": "ge", "pin": None},
                                    "2": {"name": "B", "source": "ge", "pin": None},
                                    "3": {"name": "C", "source": "ge", "pin": "GE-Proton11-9"}},
                          "keep": 2, "last_check": 0, "pending": {}, "lang": "en", "custom": {}, "bell": {}, "notified_app": ""}
        G.Main._fetch = staticmethod(lambda log: {"rels": {"ge": REL}, "app": None})
        self.w = G.Main()
        self.w.latest_rel = {"ge": REL}; self.w.latest = {"ge": REL["name"]}

    def texts(self):
        return [b.text() for b in self.w.findChildren(QPushButton)]

    def test_bells_only_where_newer_exists(self):
        self.w.refresh()
        self.assertEqual(sum("🔔" in t for t in self.texts()), 2)        # B (update) and C (pinned, newer exists)

    def test_app_banner_hidden_then_shown(self):
        self.w.refresh(); self.assertTrue(self.w.appbanner.isHidden())
        self.w.app_info = {"version": "9.9.9", "tag": "v9.9.9", "page": "p", "notes": ""}
        self.w.refresh(); self.assertFalse(self.w.appbanner.isHidden())
        self.assertIn("9.9.9", self.w.ab_title.text())

    def test_apply_button_only_when_pending(self):
        self.w.refresh(); self.assertTrue(self.w.b_apply.isHidden())
        self.w.c["pending"] = {"2": "GE-Proton11-12-x86_64"}
        self.w.refresh(); self.assertFalse(self.w.b_apply.isHidden())

    def test_dialogs_open_without_errors(self):
        QDialog.exec = lambda self: 0
        P.releases = lambda s, n=30: [REL]
        P.steam_games = lambda: {"9": "Game"}
        self.w.add_game(); self.w.pick_version("2"); self.w.about("2"); self.w.settings()

    def switches(self):
        return self.w.findChildren(G.Switch, "autoswitch")

    def test_clicking_the_switch_turns_auto_off_and_persists(self):
        saved = []; P.save = lambda c: saved.append(json.loads(json.dumps(c)))
        self.w.check_now = lambda: None
        self.w.refresh(); sw = self.switches()[1]                       # game B: auto on, up to date? (B has a newer release)
        self.assertTrue(sw.isChecked())
        QTest.mouseClick(sw, Qt.LeftButton)                              # a real click
        self.assertFalse(self.w.c["games"]["2"]["auto"]); self.assertTrue(saved and saved[-1]["games"]["2"]["auto"] is False)
        self.assertFalse(self.switches()[1].isChecked())                 # card rebuilt, switch is off
        self.assertTrue(any("Update now" in t for t in self.texts()))    # off + newer exists -> manual button

    def test_clicking_switch_on_clears_pin(self):
        P.save = lambda c: None; self.w.check_now = lambda: None
        self.w.refresh(); sw = self.switches()[2]                        # game C is pinned -> switch shows OFF
        self.assertFalse(sw.isChecked())
        QTest.mouseClick(sw, Qt.LeftButton)
        self.assertIsNone(self.w.c["games"]["3"]["pin"]); self.assertTrue(self.w.c["games"]["3"]["auto"])

    def test_off_chip_when_auto_off_and_up_to_date(self):
        self.w.c["games"]["1"]["auto"] = False; self.w.refresh()          # A is up to date
        self.assertEqual(self.w.status("1", self.w.c["games"]["1"])[0], "off")

    def test_global_switch_in_settings(self):
        saved = []; P.save = lambda c: saved.append(c.get("auto_global"))
        def fake(self_d):
            sw = [s for s in self_d.findChildren(G.Switch)][0]; QTest.mouseClick(sw, Qt.LeftButton); return 1
        QDialog.exec = fake
        self.w.settings()
        self.assertFalse(self.w.c["auto_global"]); self.assertIn(False, saved)

    def test_ukrainian_window(self):
        import i18n; i18n.set_lang("uk"); w = G.Main()
        self.assertEqual(w.windowTitle(), "Оновлювач Proton"); i18n.set_lang("en")


if __name__ == "__main__":
    unittest.main()
